function minSpeed(piles, hours) {
  let lo = 1, hi = Math.max(...piles) //@init
  while (lo < hi) { //@loop
    const mid = (lo + hi) >> 1 //@mid
    const need = piles.reduce((sum, p) => sum + Math.ceil(p / mid), 0) //@need
    if (need <= hours) hi = mid //@fits
    else lo = mid + 1 //@slow
  }
  return lo //@done
}

