function longestPiece(lengths, k) {
  let lo = 0
  let hi = Math.max(0, ...lengths)
  while (lo < hi) {
    const mid = (lo + hi + 1) >> 1
    const pieces = lengths.reduce((sum, len) => sum + Math.floor(len / mid), 0)
    // If mid gives at least k pieces, keep it: move lo up. Otherwise move hi down.
    hi = mid - 1
  }
  return lo
}

