function longestPiece(lengths: number[], k: number): number {
  let lo = 0
  let hi = Math.max(0, ...lengths)
  while (lo < hi) {
    const mid = (lo + hi + 1) >> 1
    const pieces = lengths.reduce((sum, len) => sum + Math.floor(len / mid), 0)
    if (pieces >= k) lo = mid
    else hi = mid - 1
  }
  return lo
}
